package ru.truetv.launcher;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.text.SimpleDateFormat;
import java.util.*;

public final class HomeActivity extends Activity implements AppCatalog.Listener,StatusWatch.Listener {
    private String appearance;private final ConfirmRelease confirmRelease=new ConfirmRelease();private int pendingSlot=-1;private String pendingBefore="";private long renderedLayout,renderedSlots;private View desktopRoot;private List<AppCatalog.Entry> renderedApps;
    public Board board;public LinearLayout header;private ClockFace clock,date;private TextView vpn,btCount,version;private SettingsStore settings;private AppCatalog catalog;private StatusWatch status;private final Handler timer=new Handler(Looper.getMainLooper());private int moving=-1;private boolean foreground;
    private final Runnable minute=new Runnable(){public void run(){updateClock();if(foreground)timer.postDelayed(this,60000-System.currentTimeMillis()%60000);}};
    protected void onCreate(Bundle state){appearance=Ui.prepare(this);super.onCreate(state);if(!homeEntry(getIntent())){startActivity(homeIntent(this));if(isTaskRoot())finishAndRemoveTask();else finish();return;}settings=new SettingsStore(this);catalog=AppCatalog.get(this);if(state!=null){pendingSlot=state.getInt("pending_slot",-1);pendingBefore=state.getString("pending_before","");}build();}
    static Intent homeIntent(Context context){return new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).setPackage(context.getPackageName()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);}
    private static boolean homeEntry(Intent intent){return intent!=null&&Intent.ACTION_MAIN.equals(intent.getAction())&&intent.hasCategory(Intent.CATEGORY_HOME);}
    private View nav(String glyph,String description,Runnable action){FrameLayout hit=new FrameLayout(this){private final android.graphics.Paint p=new android.graphics.Paint();protected void dispatchDraw(android.graphics.Canvas c){super.dispatchDraw(c);if(hasFocus()){p.setColor(Ui.ink(getContext()));c.drawRect(Ui.dp(getContext(),10),getHeight()-Ui.dp(getContext(),2),getWidth()-Ui.dp(getContext(),10),getHeight(),p);}}};if(Build.VERSION.SDK_INT>=26)hit.setDefaultFocusHighlightEnabled(false);hit.setId(View.generateViewId());hit.setFocusable(true);hit.setClickable(true);hit.setContentDescription(description);hit.setOnFocusChangeListener((v,focus)->v.invalidate());Glyph icon=new Glyph(this,glyph);FrameLayout.LayoutParams image=new FrameLayout.LayoutParams(Ui.dp(this,32),Ui.dp(this,32),Gravity.LEFT|Gravity.CENTER_VERTICAL);image.leftMargin=Ui.dp(this,10);hit.addView(icon,image);hit.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(Ui.dp(this,glyph.equals("bluetooth")?60:52),Ui.dp(this,52));p.rightMargin=Ui.dp(this,18);header.addView(hit,p);return hit;}
    private void build(){Ui.bars(this);if(settings.flag("wallpaper",false))getWindow().addFlags(WindowManager.LayoutParams.FLAG_SHOW_WALLPAPER);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SHOW_WALLPAPER);
        LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(Ui.dp(this,24),Ui.dp(this,16),Ui.dp(this,24),Ui.dp(this,10));Ui.backdrop(this,root);desktopRoot=root;setContentView(root);
        header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);root.addView(header,new LinearLayout.LayoutParams(-1,Ui.dp(this,64)));
        View apps=nav("apps",Ui.word(this,"Меню приложений","Applications"),()->openCatalog(-1));nav("folder",Ui.word(this,"Файловый менеджер","File manager"),()->startActivity(new Intent(this,FileActivity.class)));nav("wifi_folder",Ui.word(this,"Принять файл по Wi-Fi","Receive file over Wi-Fi"),()->startActivity(new Intent(this,ShareSettingsActivity.class)));nav("tune",Ui.word(this,"Настройки лаунчера","Launcher settings"),()->startActivity(new Intent(this,SettingsActivity.class)));nav("settings",Ui.word(this,"Системные настройки","System settings"),()->Ui.launch(this,new Intent("android.settings.SETTINGS")));
        View bt=nav("bluetooth","Bluetooth",()->BluetoothScreens.openSavedOrChoose(this));bt.setOnLongClickListener(v->{BluetoothScreens.controls(this);return true;});btCount=Ui.label(this,"",14);btCount.setGravity(Gravity.CENTER);FrameLayout.LayoutParams count=new FrameLayout.LayoutParams(Ui.dp(this,24),Ui.dp(this,32),Gravity.LEFT|Gravity.CENTER_VERTICAL);count.leftMargin=Ui.dp(this,36);((FrameLayout)bt).addView(btCount,count);btCount.setVisibility(View.INVISIBLE);
        nav("power",Ui.word(this,"Питание телевизора","TV power"),()->Controls.powerSheet(this));vpn=Ui.label(this,"VPN\nON",14);vpn.setGravity(Gravity.CENTER);vpn.setVisibility(View.INVISIBLE);header.addView(vpn,new LinearLayout.LayoutParams(Ui.dp(this,52),Ui.dp(this,52)));
        LinearLayout time=new LinearLayout(this);time.setGravity(Gravity.CENTER_VERTICAL|Gravity.RIGHT);date=new ClockFace(this,15,true);clock=new ClockFace(this,25,false);LinearLayout.LayoutParams d=new LinearLayout.LayoutParams(0,-2,1);d.rightMargin=Ui.dp(this,16);time.addView(date,d);time.addView(clock,new LinearLayout.LayoutParams(-2,-2));header.addView(time,new LinearLayout.LayoutParams(0,-2,1));
        board=new Board(this);root.addView(board,new LinearLayout.LayoutParams(-1,0,1));board.header(apps,(left,right)->{int start=Math.max(0,left-Ui.dp(this,10)),end=Math.max(0,board.getWidth()-right);int controls=Ui.dp(this,550),timeWidth=clock.naturalWidth()+(date.getVisibility()==View.GONE?0:date.naturalWidth()+Ui.dp(this,16));int budget=Math.max(0,board.getWidth()-controls-timeWidth);if(start+end>budget){float ratio=(float)budget/Math.max(1,start+end);start=Math.round(start*ratio);end=budget-start;}if(header.getPaddingLeft()!=start||header.getPaddingRight()!=end)header.setPadding(start,0,end,0);});
        for(int i=0;i<settings.columns()*settings.rows();i++){Tile tile=new Tile(this,false);bindTile(tile,i);board.addView(tile);}
        for(int i=0;i<7;i++){View button=header.getChildAt(i);button.setNextFocusLeftId(header.getChildAt((i+6)%7).getId());button.setNextFocusRightId(header.getChildAt((i+1)%7).getId());if(board.getChildCount()>0)button.setNextFocusDownId(board.getChildAt(0).getId());}
        version=Ui.label(this,"v"+BuildConfig.VERSION_NAME,11);version.setGravity(Gravity.RIGHT);version.setTextColor(Ui.muted(this));root.addView(version,new LinearLayout.LayoutParams(-1,-2));renderedLayout=settings.layoutRevision();renderedSlots=settings.slotsRevision();renderedApps=catalog.snapshot();updateClock();if(settings.flag("keep_awake",false))root.setKeepScreenOn(true);
    }
    private void bindTile(Tile tile,int slot){String assigned=settings.slot(slot);AppCatalog.Entry found=catalog.find(assigned);if(found==null&&!assigned.isEmpty())found=new AppCatalog.Entry(assigned,assigned+Ui.word(this,catalog.loaded()?" (недоступно)":" (загрузка)",catalog.loaded()?" (unavailable)":" (loading)"),false,false,null,0,"");final AppCatalog.Entry entry=found;tile.bind(entry,slot);tile.setOnClickListener(v->{if(moving>=0){int from=moving;cancelMove();if(from!=slot){settings.exchange(from,slot);refreshTile(from);refreshTile(slot);}return;}if(entry==null)openCatalog(slot);else if(!catalog.launch(entry))Ui.info(this,entry.pkg);});tile.setOnLongClickListener(v->{if(entry==null)return false;appActions(entry,slot);return true;});}
    private void refreshTile(int slot){bindTile((Tile)board.getChildAt(slot),slot);renderedSlots=settings.slotsRevision();}
    private void refreshTiles(){for(int i=0;i<board.getChildCount();i++)bindTile((Tile)board.getChildAt(i),i);renderedSlots=settings.slotsRevision();renderedApps=catalog.snapshot();}
    private void rebuild(){View focused=board.getFocusedChild();int slot=focused instanceof Tile?((Tile)focused).slot:-1;build();if(slot>=0&&slot<board.getChildCount())board.getChildAt(slot).requestFocusFromTouch();}
    private void cancelMove(){if(moving>=0&&moving<board.getChildCount())board.getChildAt(moving).setAlpha(1f);moving=-1;}
    // One catalog Activity saves the slot and finishes. Return updates the existing tile.
    private void openCatalog(int slot){pendingSlot=slot;pendingBefore=slot>=0?settings.slot(slot):"";startActivity(new Intent(this,CatalogActivity.class).putExtra("slot",slot));}
    protected void onSaveInstanceState(Bundle out){out.putInt("pending_slot",pendingSlot);out.putString("pending_before",pendingBefore);super.onSaveInstanceState(out);}
    protected void onNewIntent(Intent intent){super.onNewIntent(intent);if(!homeEntry(intent)){startActivity(homeIntent(this));return;}setIntent(intent);cancelMove();}
    public boolean dispatchKeyEvent(KeyEvent event){int code=event.getKeyCode();if((code==KeyEvent.KEYCODE_DPAD_CENTER||code==KeyEvent.KEYCODE_ENTER||code==KeyEvent.KEYCODE_NUMPAD_ENTER)&&confirmRelease.consume(event.getAction()==KeyEvent.ACTION_DOWN,event.getRepeatCount(),event.getDownTime(),event.getEventTime()))return true;return super.dispatchKeyEvent(event);}

    private void appActions(AppCatalog.Entry entry,int slot){ActionSheet.showApp(this,entry,AppMenus.ordered(this,entry,
        new ActionSheet.Item(Ui.word(this,"Убрать с рабочего стола","Remove from desktop"),"remove",()->{settings.assign(slot,"");refreshTile(slot);}),
        new ActionSheet.Item(Ui.word(this,"Заменить приложение","Replace app"),"replace",()->openCatalog(slot)),
        new ActionSheet.Item(Ui.word(this,"Переместить","Move"),"move",()->{moving=slot;board.getChildAt(slot).setAlpha(.5f);Ui.toast(this,"Выберите место и нажмите OK. Назад — отмена.","Choose a destination and press OK. Back cancels.");}),
        new ActionSheet.Item(Ui.word(this,"Закрыть приложение","Close app"),"close",()->Controls.stop(this,entry.pkg,false),()->Controls.ready(this)),
        new ActionSheet.Item(Ui.word(this,"Перезапустить приложение","Restart app"),"restart",()->Controls.stop(this,entry.pkg,true),()->Controls.ready(this)),
        new ActionSheet.Item(Ui.word(this,"Удалить приложение","Uninstall app"),"delete",()->Ui.uninstall(this,entry.pkg)),
        new ActionSheet.Item(Ui.word(this,"Открыть в маркете / обновить","Open in store / update"),"market",()->Ui.market(this,entry.pkg)),
        new ActionSheet.Item(Ui.word(this,"Свойства приложения","App info"),"info",()->Ui.info(this,entry.pkg))));
    }
    private void updateClock(){if(clock==null)return;String font=settings.text("clock_font","medium");clock.content(android.text.format.DateFormat.getTimeFormat(this).format(new Date()),font);String format=settings.text("date_format","words");date.setVisibility(format.equals("hidden")?View.GONE:View.VISIBLE);date.content(new SimpleDateFormat(format.equals("numeric")?"dd/MM/yyyy":"d MMMM yyyy",getResources().getConfiguration().locale).format(new Date()),font);}
    protected void onResume(){super.onResume();if(settings==null)return;if(!Ui.appearance(this).equals(appearance)){recreate();return;}foreground=true;cancelMove();int added=pendingSlot;boolean changed=added>=0&&!settings.slot(added).equals(pendingBefore);pendingSlot=-1;pendingBefore="";if(renderedLayout!=settings.layoutRevision())rebuild();else if(renderedApps!=catalog.snapshot()||renderedSlots!=settings.slotsRevision()&&(added<0||added>=board.getChildCount()))refreshTiles();else if(added>=0&&added<board.getChildCount()&&renderedSlots!=settings.slotsRevision())refreshTile(added);desktopRoot.setKeepScreenOn(settings.flag("keep_awake",false));updateClock();if(changed&&added<board.getChildCount()){confirmRelease.afterPicker(SystemClock.uptimeMillis());board.getChildAt(added).requestFocusFromTouch();}catalog.listen(this);if(status!=null)status.stop();status=new StatusWatch(this,this);status.start();timer.removeCallbacks(minute);timer.post(minute);ActionSheet.refreshActive();
        if(Build.VERSION.SDK_INT>=31&&settings.flag("bt_count",true)&&!settings.flag("bt_asked",false)){settings.data.edit().putBoolean("bt_asked",true).apply();requestPermissions(new String[]{Manifest.permission.BLUETOOTH_CONNECT},42);}}
    protected void onPause(){foreground=false;timer.removeCallbacks(minute);if(status!=null)status.stop();if(catalog!=null)catalog.unlisten(this);super.onPause();}
    public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)Ui.bars(this);}
    public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(status!=null){status.stop();status.start();}}
    public void onBackPressed(){cancelMove();}
    public void appsChanged(){if(foreground){refreshTiles();if(status!=null)status.refresh();}}
    public List<String> visiblePackages(){ArrayList<String> list=new ArrayList<>();for(int i=0;i<board.getChildCount();i++){String pkg=((Tile)board.getChildAt(i)).pkg;if(!pkg.isEmpty())list.add(pkg);}return list;}
    public void status(boolean connected,String owner,int devices,Set<String> live){vpn.setVisibility(connected?View.VISIBLE:View.INVISIBLE);vpn.setContentDescription(connected?(owner==null?"VPN ON":"VPN ON · "+owner):"");btCount.setVisibility(devices>0?View.VISIBLE:View.INVISIBLE);btCount.setText(devices>99?"99+":String.valueOf(devices));for(int i=0;i<board.getChildCount();i++){Tile tile=(Tile)board.getChildAt(i);tile.running(live.contains(tile.pkg));}}
}
